<?php
require __DIR__.'/config.php';require_login();$pdo=db();$st=$pdo->prepare('SELECT s.*,c.name customer,c.phone,u.name cashier FROM sales s LEFT JOIN customers c ON c.id=s.customer_id LEFT JOIN users u ON u.id=s.user_id WHERE s.id=?');$st->execute([(int)($_GET['id']??0)]);$sale=$st->fetch();if(!$sale){http_response_code(404);exit('Receipt not found.');}$st=$pdo->prepare('SELECT * FROM sale_items WHERE sale_id=?');$st->execute([$sale['id']]);$items=$st->fetchAll();$pageTitle='Receipt';require __DIR__.'/partials/header.php';?><div class="receipt-actions"><a href="pos.php" class="btn secondary">← Back to POS</a><button class="btn primary" onclick="window.print()">Print receipt</button></div><article class="receipt"><div class="receipt-brand"><div class="brand-mark">J</div><h1>Jobili</h1><p>Store Management System</p></div><hr><div class="receipt-meta"><span>Receipt</span><b><?=e($sale['receipt_no'])?></b><span>Date</span><b><?=e($sale['created_at'])?></b><span>Customer</span><b><?=e($sale['customer']??'Walk-in')?></b><span>Cashier</span><b><?=e($sale['cashier']??'—')?></b></div><table><thead><tr><th>Item</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><?=e($it['product_name'])?></td><td><?=e($it['quantity'])?></td><td><?=money($it['unit_price'])?></td><td><?=money($it['line_total'])?></td></tr><?php endforeach;?></tbody></table><div class="receipt-totals"><div><span>Subtotal</span><b><?=money($sale['subtotal'])?></b></div><div><span>Discount</span><b><?=money($sale['discount'])?></b></div><div class="grand-total"><span>TOTAL</span><b><?=money($sale['total'])?></b></div><div><span>Payment method</span><b><?=e(strtoupper($sale['payment_method']))?></b></div><div><span>Amount paid</span><b><?=money($sale['amount_paid'])?></b></div><?php if($sale['status']!=='utang'):?><div><span>Change</span><b><?=money($sale['change_due'])?></b></div><?php else:?><div><span>Balance due</span><b><?=money($sale['total']-$sale['amount_paid'])?></b></div><?php endif;?></div><p class="receipt-thanks">Thank you for shopping at Jobili!</p></article><?php require __DIR__.'/partials/footer.php';?>